INSERT INTO departments (id, slug, name, short_description, full_description, mission, vision, values, objectives, established_date, logo_key, cover_image_key, cover_image, accent_color, stats, programs, telegram_link, telegram_chat_id, registration_status, registration_fields, requirements)
VALUES ('dept-halqa', 'halqa', '{"ar":"حلقة دار القرآن","en":"Dar Al-Quran Study Circle","am":"ዳር አል-ቁርአን የጥናት ክበብ","om":"Marii Qorannoo Daar Al-Quraan"}', '{"ar":"حلقة علمية لدراسة كتب العقيدة والفقه والحديث بعد صلاة العصر","en":"A study circle for learning books on Aqidah, Fiqh, and Hadith after Asr prayer","am":"ከአስር ሰዓት በኋላ የዐቂደ፣ ፊቅህ እና ሐዲስ መጻሕፍትን ለማጥናት የሚዘጋጅ ክበብ","om":"Galgala sanaa Aqiidaa, Fiqh fi Hadiisaa qorachuuf naannoo qorannoo"}', '{"ar":"تأسست حلقة دار القرآن عام 1443هـ كحلقة علمية تجمع طلاب العلم لدراسة كتب التراث الإسلامي. تعقد الحلقة بعد صلاة العصر إلى المغرب، وتُدرس فيها مجموعة من الكتب المهمة في العقيدة والفقه والحديث والسيرة.","en":"Dar Al-Quran Study Circle was established in 1443H as a study circle gathering students of knowledge to study classical Islamic texts. The circle meets from Asr to Maghrib prayer, studying a collection of important books on Aqidah, Fiqh, Hadith, and Sira.","am":"የዳር አል-ቁርአን የጥናት ክበብ በ1443ሂ ተመሰረተ። ከአስር ሰዓት እስከ ማክሪብ ይካሄዳል።","om":"Marii qorannoo Daar Al-Quraan 1443H kan hundeeffame. Galgala Asr irraa hanga Maghribatti kan taphatamu."}', '{"ar":"نشر العلم الشرعي ودراسة كتب التراث الإسلامي بين طلاب العلم","en":"Spreading Islamic knowledge and studying classical Islamic texts among students of knowledge","am":"የእስላም ሳይንስን ማስፋት እና መጻሕፍትን ማጥናት","om":"Beekumsa Islaamaa faca''uu fi kitaabota seenaa qorachuu"}', '{"ar":"إيجاد مجتمع علمي يعتني بكتب التراث ويُتقن فهم الدين","en":"Creating a scholarly community that cares for classical texts and masters understanding of religion","am":"መጻሕፍትን ለሚያጠና ማህበረሰብ መፍጠር","om":"Hawaasa qorannoo kitaabota of keessatti qabu uumuu"}', '[{"ar":"الإخلاص في طلب العلم","en":"Sincerity in seeking knowledge","am":"በእውቀት ፍለጋ ቅንነት","om":"Beekumsa barbaachuu qajeelummaa"},{"ar":"التدريج في الدراسة","en":"Progressive study","am":"ቀጣይ ጥናት","om":"Itti fufiinsa qorannoo"},{"ar":"العمل بالعلم","en":"Acting upon knowledge","am":"በእውቀት መንቀስ","om":"Beekumsa hojiirra oolfuu"}]', '[{"ar":"دراسة كتب أصول الدين وفروعه","en":"Study books of Usul and Furu","am":"መጻሕፍትን ማጥናት","om":"Kitaabota Usul fi Furu qorachuu"},{"ar":"تأهيل طلاب العلم للتعليم","en":"Qualify students for teaching","am":"ተማሪዎችን ለማሰልጠን","om":"Barattoota barsiisuuf qopheessuu"}]', '1443 هـ', 'halqa', 'halqa', 'https://images.pexels.com/photos/32668037/pexels-photo-32668037.jpeg?auto=compress&cs=tinysrgb&w=1600', '{"base":"#2563EB","accent":"#FBBF24"}', '[{"label":{"ar":"كتاب مُدرس","en":"Books studied","am":"መጻሕፍት ተገብሮ","om":"Kitaabota qoratame"},"value":8},{"label":{"ar":"طالب علم","en":"Students","am":"ተማሪ","om":"Barattoota"},"value":45},{"label":{"ar":"سنوات النشاط","en":"Years active","am":"የንቁ ዓመታት","om":"Waggaa sochii"},"value":4}]', '[{"name":{"ar":"الأصول الثلاثة","en":"Usul al-Thalatha","am":"ኡሱል አስ-ሳላሳ","om":"Usul al-Thalaatha"},"icon":"gem","description":{"ar":"الأساس الأول: معرفة الله ورسوله ودين الإسلام، بفهم صحيح يحمي من الشرك والبدع.","en":"The first foundation: knowing Allah, His Messenger, and the religion of Islam — a sound understanding that protects from polytheism and innovation.","am":"የመጀመሪያው መሠረት: አላህን፣ መልእክተኛውን እና የእስላም ሃይማኖትን መረዳት — ከአሳምና ከብድነት የሚጠብቅ ትክክለኛ ግንዛቤ።","om":"Bukuu jalqabaa: Waaqayyoo, Ergamaa Isaa fi amantaa Islaamaa hubachuu — shirkaa fi bala''aa irraa eegu."}},{"name":{"ar":"رياض الصالحين","en":"Riyad al-Salihin","am":"ሪያድ አስ-ሳሊሂን","om":"Riyaad al-Saalihiin"},"icon":"scroll","description":{"ar":"باقة من أنقى الأحاديث في الآداب والأخلاق والزهد، تُربي القلب وتُصلح العمل.","en":"A bouquet of the purest hadiths on manners, morals, and asceticism — nurturing the heart and refining deeds.","am":"ስለ አክብሮት፣ ምግባርና ተግባር ያሉ ንፁሓን ሐዲሶች — ልብን ማሳደግና ተግባርን ማስተካከል።","om":"Hadiisa qulqulluu amantaa fi hojii irratti — onnee guddisuu fi hojii sirreessuu."}},{"name":{"ar":"بلوغ المرام","en":"Bulugh al-Maram","am":"ቡሉግ አል-ማራም","om":"Bulugh al-Maraam"},"icon":"bookOpen","description":{"ar":"أدلة الأحكام الفقهية من أصح الأحاديث، يرقى بالطالب نحو فقه النصوص.","en":"Evidence of fiqh rulings from the most authentic hadiths — elevating the student toward understanding the texts.","am":"ከትክክለኛዎቹ ሐዲሶች የፊቅህ ሕግ ማስረጃዎች — ተማሪውን ጽሑፎችን ወደ መረዳት ማሳደግ።","om":"Raga fiqhii hadiisa dhugaa irraa — barataa barruu hubachuu ol kaasu."}},{"name":{"ar":"التجريد","en":"Tajrid","am":"ተጅሪድ","om":"Tajriid"},"icon":"gem","description":{"ar":"تجريد التوحيد وتنقيته من شوائب البدع، تأصيل لعقيدة سلفية نقية.","en":"Stripping Tawhid of the impurities of innovation — grounding a pure Salafi creed.","am":"የተውሂድን ከብድነት ብክለት ማንጸባረቅ — ንፁሕ የሰላፊ እምነት መመስረት።","om":"Tawhiida bishaan bala''aa irraa qulqulleessuu — amantaa Salafaa qulqulluu ijaruu."}},{"name":{"ar":"تحفة/تملحة","en":"Tuhfat/Temliha","am":"ቱህፌ/ተምሊሀ","om":"Tuhfat/Temliha"},"icon":"mic","description":{"ar":"متنٌ في النحو والصرف، يفتح باب إعراب القرآن وفهم تركيبه.","en":"A text on grammar and morphology — opening the door to parsing the Quran and understanding its structure.","am":"ስለ ሰዋሰውና ስለ ቅርጽ የሆነ ጽሑፍ — የቁርአንን ሰዋሰው መረዳትና ግንባሩን መክፈት።","om":"Barreeffama sirna jechootaa fi jechoota ciccimuu — Quraana fe''uu fi ijaarsa isaa hubachuu banuu."}},{"name":{"ar":"عمدة الأحكام","en":"Umdat al-Ahkam","am":"ኡምደ አል-አህካም","om":"Umdat al-Ahkaam"},"icon":"scale","description":{"ar":"أحاديث الأحكام الفقهية الكبرى، مع بيان مذاهب العلماء وأدلتهم.","en":"The major hadiths of fiqh rulings, with clarification of scholars'' positions and their evidence.","am":"ዋናዎቹ የፊቅህ ሕግ ሐዲሶች፣ የሊቃውንጮች አቋምና ማስረጃዎች አብራራት።","om":"Hadiisa fiqhii guddaa, yaada ogeeyyii fi raga isaanii ifa gochuu."}},{"name":{"ar":"السفينة","en":"Safina","am":"ሰፊና","om":"Safiina"},"icon":"mapPin","description":{"ar":"متنٌ جامع في الفقه الشافعي، يجمع أبواب العبادات في وضوح وإيجاز.","en":"A comprehensive text on Shafi''i fiqh, gathering the chapters of worship with clarity and brevity.","am":"ስለ ሻፊዒ ፊቅህ ሙሉ ጽሑፍ — የአምልኮ ምዕራፎችን በግልጽነትና በአጭረኝነት የሚያካትት።","om":"Barreeffama fiqhii Shafi''ii guddaa — kutaa ibaadaa ifa fi gabaabaa qabachuu."}},{"name":{"ar":"كتب السيرة","en":"Sira books","am":"የሲራ መጻሕፍት","om":"Kitaabota Siiraa"},"icon":"scroll","description":{"ar":"قراءة في سيرة النبي ﷺ وأيام الصحابة، ليقتدي بها المسلم في حياته.","en":"A reading in the biography of the Prophet ﷺ and the days of the companions — for the Muslim to follow in their footsteps.","am":"የነቢዩ ﷺ የሕይወት ታሪክና የሰሃቦች ቀኖና ማንበብ — ሙስሊሙ በእሳታቸው እንትተት ዘንድ።","om":"Seenaa jireenya Rasulaa ﷺ fi sahaaba — Muslimni isaan hordofuu."}}]', 'https://t.me/daralquran_halqa', '-1001234567892', 'coming_soon', '[{"name":"fullName","label":{"ar":"الاسم الكامل","en":"Full Name","am":"ሙሉ ስም","om":"Maqaa guddaa"},"type":"text","required":true},{"name":"phone","label":{"ar":"رقم الهاتف","en":"Phone Number","am":"ስልክ ቁጥር","om":"Lakkoofsa bilbila"},"type":"tel","required":true},{"name":"age","label":{"ar":"العمر","en":"Age","am":"ዕድሜ","om":"Umuri"},"type":"number","required":true},{"name":"studyTopic","label":{"ar":"موضوع الدراسة","en":"Study Topic","am":"የጥናት ርዕስ","om":"Mata duree qorannoo"},"type":"select","required":true,"options":[{"ar":"الفقه","en":"Fiqh","am":"ፊቅህ","om":"Fiqh"},{"ar":"العقيدة","en":"Aqeedah","am":"አቂዳ","om":"Aqiidah"},{"ar":"الحديث","en":"Hadith","am":"ሐዲስ","om":"Hadiis"},{"ar":"التفسير","en":"Tafsir","am":"ተፍሲር","om":"Tafsiir"},{"ar":"السيرة","en":"Seerah","am":"ሲራ","om":"Seera"}]},{"name":"preferredTime","label":{"ar":"الوقت المفضل","en":"Preferred Time","am":"የተመረጠ ጊዜ","om":"Yeroo filatama"},"type":"select","required":false,"options":[{"ar":"بعد العصر","en":"After Asr","am":"ከአስር በኋላ","om":"Booda Asr"},{"ar":"بعد المغرب","en":"After Maghrib","am":"ከማግሪብ በኋላ","om":"Booda Magrib"},{"ar":"بعد العشاء","en":"After Isha","am":"ከኢሻ በኋላ","om":"Booda Isha"}]},{"name":"notes","label":{"ar":"ملاحظات","en":"Notes","am":"ማስታወሻዎች","om":"Gabaaboo"},"type":"textarea","required":false}]', '{"ar":"الشروط: أن يكون الطالب مسلماً، بالغاً، لديه معرفة أساسية بالقراءة والكتابة، ملتزماً بحضور الحلقة بعد صلاة العصر بانتظام، ولديه نية صادقة في طلب العلم الشرعي.","en":"Requirements: The student must be Muslim, adult, with basic reading and writing skills, committed to attending the circle regularly after Asr prayer, and sincere in seeking Islamic knowledge.","am":"ሁኔታዎች፡ ተማሪው ሙስሊም መሆን፣ የጎሠኝነት ዕድሜ መድረስ፣ መንበብና መጻፍ የመማር መሠረታዊ ችሎታ መኖር፣ ከአስር ሰዓት በኋላ በመደበኛነት ክበቡን ለመከታተል መቻሉ።","om":"Eegumsa: Barataan Muslimaatti, dhirsa, dubbisuu fi barreessuu beekuu, galgala Asr booda marii hordofuu, beekumsa Islaamaa barachuu qajeelummaa qabuu."}')
ON CONFLICT (slug) DO NOTHING;